-- Arbeitsrecht Berufsbildung > Rechte von Arbeitgebern > Festlegung des Ausbildungsplans (§ 11 BBiG)
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Darf ein Ausbildungsbetrieb den Ausbildungsplan für einen Fachinformatiker selbst festlegen?', 2, '[{"text": "Ja", "correct": true, "because": "§ 11 BBiG gibt dem Arbeitgeber dieses Recht"}, {"text": "Nein", "correct": false, "because": "Festlegung ist Aufgabe des Betriebs"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss der Ausbildungsplan eines Fachinformatikers dem Ausbildungsrahmenplan entsprechen?', 2, '[{"text": "Ja", "correct": true, "because": "§ 11 BBiG verlangt die Berücksichtigung des Rahmenplans"}, {"text": "Nein", "correct": false, "because": "Rahmenplan ist bindend"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Fachinformatiker den Ausbildungsplan selbst bestimmen?', 2, '[{"text": "Nein", "correct": true, "because": "§ 11 BBiG legt die Festlegung beim Arbeitgeber"}, {"text": "Ja", "correct": false, "because": "Auszubildende haben kein Mitspracherecht"}]'),
('00000000-0000-0000-0000-000000000000', 'Darf der Ausbildungsplan eines Fachinformatikers während der Ausbildung geändert werden?', 2, '[{"text": "Ja", "correct": true, "because": "§ 11 BBiG erlaubt Anpassungen bei Bedarf"}, {"text": "Nein", "correct": false, "because": "Änderungen sind zulässig"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss der Ausbildungsplan eines Fachinformatikers schriftlich festgehalten werden?', 2, '[{"text": "Ja", "correct": true, "because": "§ 11 BBiG fordert eine schriftliche Form"}, {"text": "Nein", "correct": false, "because": "Schriftform ist vorgeschrieben"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche gesetzliche Grundlage gibt dem Arbeitgeber das Recht, den Ausbildungsplan für einen Fachinformatiker festzulegen?', 2, '[{"text": "§ 11 BBiG", "correct": true, "because": "Regelt die Festlegung des Ausbildungsplans"}, {"text": "§ 13 BBiG", "correct": false, "because": "Bezieht sich auf Pflichten des Auszubildenden"}, {"text": "§ 14 BBiG", "correct": false, "because": "Regelt Pflichten des Arbeitgebers"}]'),
('00000000-0000-0000-0000-000000000000', 'Was muss ein Ausbildungsplan für einen Fachinformatiker zwingend enthalten?', 3, '[{"text": "Zeitliche und sachliche Gliederung der Ausbildung", "correct": true, "because": "§ 11 BBiG schreibt dies vor"}, {"text": "Persönliche Wünsche des Auszubildenden", "correct": false, "because": "Nicht vorgeschrieben"}, {"text": "Nur allgemeine Betriebsregeln", "correct": false, "because": "Zu unspezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer legt den Ausbildungsplan für einen Fachinformatiker fest?', 2, '[{"text": "Der Ausbildungsbetrieb", "correct": true, "because": "§ 11 BBiG gibt dem Betrieb diese Aufgabe"}, {"text": "Die IHK", "correct": false, "because": "IHK überwacht nur"}, {"text": "Die Berufsschule", "correct": false, "because": "Schule hat keine Festlegungsrolle"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert, wenn ein Ausbildungsplan für einen Fachinformatiker nicht den Vorgaben entspricht?', 3, '[{"text": "Die IHK kann den Betrieb auffordern, ihn anzupassen", "correct": true, "because": "IHK überwacht die Einhaltung von § 11 BBiG"}, {"text": "Der Auszubildende muss ihn selbst ändern", "correct": false, "because": "Nicht seine Aufgabe"}, {"text": "Die Ausbildung wird automatisch beendet", "correct": false, "because": "Nicht vorgesehen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt der Ausbildungsplan eines Fachinformatikers?', 3, '[{"text": "Vermittlung der erforderlichen Fertigkeiten", "correct": true, "because": "§ 11 BBiG zielt auf Ausbildungsziele ab"}, {"text": "Maximierung der Betriebsgewinne", "correct": false, "because": "Nicht primäres Ziel"}, {"text": "Freizeitgestaltung des Auszubildenden", "correct": false, "because": "Irrelevant"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Inhalte muss ein Ausbildungsplan für einen Fachinformatiker gemäß § 11 BBiG umfassen?', 4, '[{"text": "Zeitliche Abfolge der Ausbildung", "correct": true, "because": "Vorgeschrieben nach § 11 BBiG"}, {"text": "Sachliche Gliederung der Lerninhalte", "correct": true, "because": "Teil der Planung"}, {"text": "Private Interessen des Auszubildenden", "correct": false, "because": "Nicht erforderlich"}, {"text": "Fachliche Kenntnisse wie Programmierung", "correct": true, "because": "Berufsbezogen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anforderungen muss ein Ausbildungsplan für einen Fachinformatiker erfüllen?', 3, '[{"text": "Übereinstimmung mit dem Ausbildungsrahmenplan", "correct": true, "because": "§ 11 BBiG verlangt dies"}, {"text": "Schriftliche Form", "correct": true, "because": "Gesetzlich vorgeschrieben"}, {"text": "Beliebige Gestaltung nach Betriebswunsch", "correct": false, "because": "Rahmenplan ist bindend"}, {"text": "Berücksichtigung der IHK-Vorgaben", "correct": true, "because": "IHK überwacht die Einhaltung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was kann ein Ausbildungsbetrieb im Ausbildungsplan eines Fachinformatikers festlegen?', 4, '[{"text": "Reihenfolge der Lerninhalte", "correct": true, "because": "§ 11 BBiG erlaubt dies"}, {"text": "Dauer der einzelnen Abschnitte", "correct": true, "because": "Zeitliche Gliederung"}, {"text": "Persönliche Hobbys des Auszubildenden", "correct": false, "because": "Nicht relevant"}, {"text": "Spezifische IT-Themen wie Netzwerke", "correct": true, "because": "Sachliche Gliederung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Konsequenzen drohen einem Betrieb, wenn der Ausbildungsplan eines Fachinformatikers fehlerhaft ist?', 3, '[{"text": "Verwarnung durch die IHK", "correct": true, "because": "IHK überwacht § 11 BBiG"}, {"text": "Anpassungsforderung durch die IHK", "correct": true, "because": "Korrektur ist möglich"}, {"text": "Automatische Schließung", "correct": false, "because": "Nicht vorgesehen"}, {"text": "Meldung an die Berufsschule", "correct": true, "because": "Schule kann eingebunden werden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte darf ein Ausbildungsplan eines Fachinformatikers nicht enthalten?', 3, '[{"text": "Illegale Tätigkeiten", "correct": true, "because": "Widerspricht gesetzlichen Vorgaben"}, {"text": "Nicht ausbildungsbezogene Aufgaben", "correct": true, "because": "Muss sachlich relevant sein"}, {"text": "Programmierung und Netzwerktechnik", "correct": false, "because": "Das ist zulässig"}, {"text": "Zeitliche Strukturierung", "correct": false, "because": "Vorgeschrieben"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Der Ausbildungsplan eines Fachinformatikers muss dem Rahmenplan entsprechen. b) Der Auszubildende kann ihn frei gestalten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Rahmenplan bindend, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Der Ausbildungsplan muss schriftlich festgehalten werden. b) Änderungen sind während der Ausbildung möglich.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "§ 11 BBiG fordert Schriftform und erlaubt Anpassungen"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Der Betrieb legt den Ausbildungsplan allein fest. b) Der Plan muss nur mündlich vereinbart werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Betrieb ist zuständig, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Der Ausbildungsplan dient der Strukturierung der Ausbildung. b) Er muss nur allgemeine Themen enthalten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Strukturierung ist Ziel, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Der Ausbildungsplan eines Fachinformatikers muss IT-spezifische Inhalte enthalten. b) Die IHK legt den Plan direkt fest.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "IT-Inhalte erforderlich, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

